'use strict';const test=require('node:test'),assert=require('node:assert/strict'),api=require('../../releases/v441/lts-v441-budget-model.js');
test('Malformed amounts cannot turn into available zero cash',()=>{for(const x of[null,undefined,'',' ',true,false,[],{},'NaN','Infinity'])assert.equal(api.cents(x),null);assert.equal(api.cents('0'),0);assert.equal(api.cents('-1.25'),-125);});
const day=(date,bank,liquid,shares,restricted)=>({date,fix86_columns:{saldo_final:bank,saldo_apos_d0_1:liquid,saldo_apos_rsu:shares,saldo_apos_fgts:restricted}});
test('Present cash is separate from future negative dates in each scenario',()=>{const f=api.flow({current_future:{days:[day('2026-11-12',100,150,250,250),day('2026-12-03',-20,30,130,130),day('2026-12-10',-80,-30,70,70),day('2026-12-20',-180,-130,-30,10)]}},'2026-11-12');assert.deepEqual(f.today,{date:'2026-11-12',bank:10000,liquid:15000,shares:25000,restricted:25000});assert.equal(f.bank.date,'2026-12-03');assert.equal(f.liquid.date,'2026-12-10');assert.equal(f.shares.date,'2026-12-20');assert.equal(f.shares.amount,-3000);assert.equal(f.restricted.date,null);});
test('Missing balances are unknown; a future row cannot substitute for cash today',()=>{const f=api.flow({current_future:{days:[day('2026-12-03',-20,null,130,130)]}},'2026-11-12');assert.equal(f.today,null);assert.equal(f.liquid.known,false);assert.equal(f.bank.amount,-2000);});
test('Past negatives and dates beyond 90 days do not become the short term deficit',()=>{const f=api.flow({current_future:{days:[day('2026-11-01',-1,-1,-1,-1),day('2026-11-12',100,100,100,100),day('2027-03-01',-1,-1,-1,-1)]}},'2026-11-12');assert.equal(f.bank.date,null);assert.equal(f.through,'2026-11-12');});
